from collections import defaultdict

def group_and_sort(records):
    groups = defaultdict(list)

    for record in records:
        category = record["category"]
        score = record["score"]
        groups[category].append(record)

    for category in groups:
        groups[category] = sorted(
            groups[category],
            key=lambda x: x["score"],
            reverse=True
        )

    return dict(groups)


if __name__ == "__main__":
    data = [
        {"category": "A", "name": "alpha", "score": 10},
        {"category": "B", "name": "beta", "score": 7},
        {"category": "A", "name": "gamma", "score": 15},
        {"category": "B", "name": "delta", "score": 12},
        {"category": "A", "name": "epsilon", "score": 8},
    ]

    result = group_and_sort(data)
    print(result)
