import json

def _freeze(value):
    if isinstance(value, dict):
        return ("dict", tuple(sorted((k, _freeze(v)) for k, v in value.items())))
    if isinstance(value, list):
        return ("list", tuple(_freeze(v) for v in value))
    if isinstance(value, tuple):
        return ("tuple", tuple(_freeze(v) for v in value))
    if isinstance(value, set):
        return ("set", tuple(sorted(_freeze(v) for v in value)))
    return ("atom", value)

def dedupe_json_preserve_order(items):
    seen = set()
    result = []

    for item in items:
        key = _freeze(item)
        if key not in seen:
            seen.add(key)
            result.append(item)

    return result


if __name__ == "__main__":
    data = [
        {"a": 1, "b": [1, 2]},
        {"b": [1, 2], "a": 1},   # same as first, different key order
        [1, [2, 3]],
        [1, [2, 3]],             # duplicate nested list
        {"x": {"y": 2, "z": 3}},
        {"x": {"z": 3, "y": 2}}, # same as previous, reordered nested dict
        5,
        5,                       # repeated primitive
        None,
        None,                    # repeated None
    ]

    result = dedupe_json_preserve_order(data)

    assert result == [
        {"a": 1, "b": [1, 2]},
        [1, [2, 3]],
        {"x": {"y": 2, "z": 3}},
        5,
        None,
    ]

    print(json.dumps(result, indent=2))
